namespace RonSijm.FluidHumidifier.Factories.IoT;

public class JobFactory(string resourceName = null, Action<Humidifier.IoT.Job> factoryAction = null) : ResourceFactory<Humidifier.IoT.Job>(resourceName)
{

    internal InnerJobTimeoutConfigFactory TimeoutConfigFactory { get; set; }

    internal InnerJobJobExecutionsRetryConfigFactory JobExecutionsRetryConfigFactory { get; set; }

    internal InnerJobAbortConfigFactory AbortConfigFactory { get; set; }

    internal InnerJobJobExecutionsRolloutConfigFactory JobExecutionsRolloutConfigFactory { get; set; }

    internal InnerJobSchedulingConfigFactory SchedulingConfigFactory { get; set; }

    internal InnerJobPresignedUrlConfigFactory PresignedUrlConfigFactory { get; set; }

    protected override Humidifier.IoT.Job Create()
    {
        var jobResult = CreateJob();
        factoryAction?.Invoke(jobResult);

        return jobResult;
    }

    private Humidifier.IoT.Job CreateJob()
    {
        var jobResult = new Humidifier.IoT.Job
        {
            GivenName = InputResourceName,
        };

        return jobResult;
    }
    public override void CreateChildren(Humidifier.IoT.Job result)
    {
        base.CreateChildren(result);

        result.TimeoutConfig ??= TimeoutConfigFactory?.Build();
        result.JobExecutionsRetryConfig ??= JobExecutionsRetryConfigFactory?.Build();
        result.AbortConfig ??= AbortConfigFactory?.Build();
        result.JobExecutionsRolloutConfig ??= JobExecutionsRolloutConfigFactory?.Build();
        result.SchedulingConfig ??= SchedulingConfigFactory?.Build();
        result.PresignedUrlConfig ??= PresignedUrlConfigFactory?.Build();
    }

} // End Of Class

